  .then(result => {
    console.log(result);
  })
  .catch(error => {
    console.log(error);
  });
```

---

**Example with setTimeout**

```javascript
function fetchData(){

  return new Promise((resolve, reject) => {

    setTimeout(()=>{
      resolve("Data received");
    },2000);

  });

}

fetchData().then(data => console.log(data));
```

Output after 2 seconds:

```text
Data received
```

---

**Promise Chaining**

```javascript
