public class PairSum {
    public static void main(String[] args) {
        int[] arr = {1, 5, 7, -1, 5};
        int target = 6;

        Set<Integer> seen = new HashSet<>();
        Set<String> output = new HashSet<>();

        for (int num : arr) {
