### 4. Restore List After Check 🔥🔥
```java id="pl4"
static boolean isPalindrome(Node head) {
    if (head == null || head.next == null) return true;

    Node slow = head, fast = head;

    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
    }

    // reverse second half
    Node prev = null, curr = slow;
    while (curr != null) {
        Node next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }

    Node second = prev, first = head;
    boolean result = true;

    while (second != null) {
        if (first.val != second.val) {
            result = false;
            break;
        }
        first = first.next;
        second = second.next;
    }

    // restore
    curr = prev;
    prev = null;
    while (curr != null) {
        Node next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }

    return result;
}
```

