### 1. Undirected Graph (DFS + Parent Tracking 🔥)
```java id="gdfs1"
import java.util.*;

public class CycleUndirected {

    static boolean hasCycle(int V, List<List<Integer>> adj) {
        boolean[] visited = new boolean[V];

        for (int i = 0; i < V; i++) {
            if (!visited[i] && dfs(i, -1, visited, adj)) {
                return true;
            }
        }
        return false;
    }

    static boolean dfs(int node, int parent, boolean[] visited, List<List<Integer>> adj) {
        visited[node] = true;

        for (int nei : adj.get(node)) {
            if (!visited[nei]) {
                if (dfs(nei, node, visited, adj)) return true;
            } else if (nei != parent) {
                return true;
            }
        }

        return false;
    }
}
```

