import java.util.*;

static boolean hasCycle(int V, List<List<Integer>> adj) {
    boolean[] visited = new boolean[V];

    for (int i = 0; i < V; i++) {
        if (!visited[i]) {
            Stack<int[]> stack = new Stack<>();
            stack.push(new int[]{i, -1});

            while (!stack.isEmpty()) {
                int[] curr = stack.pop();
                int node = curr[0], parent = curr[1];

                if (visited[node]) continue;
                visited[node] = true;

                for (int nei : adj.get(node)) {
                    if (!visited[nei]) {
                        stack.push(new int[]{nei, node});
                    } else if (nei != parent) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}
