import java.util.*;

static Node sort(Node head) {
    PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> a.val - b.val);

    while (head != null) {
        pq.add(head);
        head = head.next;
    }

    Node dummy = new Node(0), curr = dummy;

    while (!pq.isEmpty()) {
        curr.next = pq.poll();
        curr = curr.next;
    }

    curr.next = null;
    return dummy.next;
}
