### 5. Generic Heap Sort (Any Comparable 🔥)
```java id="hs5n3w"
import java.util.*;

public class HeapSort {
    public static void main(String[] args) {
        Integer[] arr = {4,10,3,5,1};

        heapSort(arr);

        System.out.println(Arrays.toString(arr));
    }

    static <T extends Comparable<T>> void heapSort(T[] arr) {
        int n = arr.length;

        for (int i = n/2 - 1; i >= 0; i--) heapify(arr, n, i);

        for (int i = n - 1; i > 0; i--) {
            swap(arr, 0, i);
            heapify(arr, i, 0);
        }
    }

    static <T extends Comparable<T>> void heapify(T[] arr, int n, int i) {
        int largest = i;
        int l = 2*i + 1, r = 2*i + 2;

        if (l < n && arr[l].compareTo(arr[largest]) > 0) largest = l;
        if (r < n && arr[r].compareTo(arr[largest]) > 0) largest = r;

        if (largest != i) {
            swap(arr, i, largest);
            heapify(arr, n, largest);
        }
    }

    static <T> void swap(T[] arr, int i, int j) {
        T t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
