### 2. Iterative DFS using Stack 🔥🔥
```java id="dfs2"
import java.util.*;

static void dfs(int start, List<List<Integer>> adj, int V) {
    boolean[] visited = new boolean[V];
    Stack<Integer> stack = new Stack<>();

    stack.push(start);

    while (!stack.isEmpty()) {
        int node = stack.pop();

        if (visited[node]) continue;

        visited[node] = true;
        System.out.print(node + " ");

        // reverse order (optional)
        List<Integer> neighbors = adj.get(node);
        for (int i = neighbors.size() - 1; i >= 0; i--) {
            int nei = neighbors.get(i);
            if (!visited[nei]) {
                stack.push(nei);
            }
        }
    }
}
