import java.util.*;

public class ReverseLL {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static Node reverse(Node head) {
        Stack<Node> stack = new Stack<>();

        Node curr = head;
        while (curr != null) {
            stack.push(curr);
            curr = curr.next;
        }

        Node newHead = stack.pop();
        curr = newHead;

        while (!stack.isEmpty()) {
            curr.next = stack.pop();
            curr = curr.next;
        }

        curr.next = null;
        return newHead;
    }
}
