### 1. BFS (Level Order - Most Common 🔥)
```java id="ser1"
import java.util.*;

public class Codec {

    static class Node {
        int val;
        Node left, right;
        Node(int v) { val = v; }
    }

    // Serialize
    public String serialize(Node root) {
        if (root == null) return "";

        StringBuilder sb = new StringBuilder();
        Queue<Node> q = new LinkedList<>();
        q.offer(root);

        while (!q.isEmpty()) {
            Node curr = q.poll();

            if (curr == null) {
                sb.append("null,");
                continue;
            }

            sb.append(curr.val).append(",");
            q.offer(curr.left);
            q.offer(curr.right);
        }

        return sb.toString();
    }

    // Deserialize
    public Node deserialize(String data) {
        if (data.isEmpty()) return null;

        String[] arr = data.split(",");
        Node root = new Node(Integer.parseInt(arr[0]));

        Queue<Node> q = new LinkedList<>();
        q.offer(root);

        int i = 1;

        while (!q.isEmpty()) {
            Node curr = q.poll();

            if (!arr[i].equals("null")) {
                curr.left = new Node(Integer.parseInt(arr[i]));
                q.offer(curr.left);
            }
            i++;

            if (!arr[i].equals("null")) {
                curr.right = new Node(Integer.parseInt(arr[i]));
                q.offer(curr.right);
            }
            i++;
        }

        return root;
    }
}
```

