    public String serialize(Node root) {
        StringBuilder sb = new StringBuilder();
        dfs(root, sb);
        return sb.toString();
    }

    private void dfs(Node root, StringBuilder sb) {
        if (root == null) {
            sb.append("null,");
            return;
        }

        sb.append(root.val).append(",");
        dfs(root.left, sb);
        dfs(root.right, sb);
    }

    // Deserialize
    int index = 0;

    public Node deserialize(String data) {
        String[] arr = data.split(",");
        return build(arr);
    }

    private Node build(String[] arr) {
        if (arr[index].equals("null")) {
            index++;
            return null;
        }

        Node root = new Node(Integer.parseInt(arr[index++]));
        root.left = build(arr);
        root.right = build(arr);

        return root;
    }
}
