### 4. Iterative (Postorder using Stack 🔥)
```java id="mps4"
import java.util.*;

static int maxPathSum(Node root) {
    Map<Node, Integer> map = new HashMap<>();
    Stack<Node> stack = new Stack<>();
    Node curr = root, last = null;
    int max = Integer.MIN_VALUE;

    while (curr != null || !stack.isEmpty()) {
        if (curr != null) {
            stack.push(curr);
            curr = curr.left;
        } else {
            Node peek = stack.peek();

            if (peek.right != null && last != peek.right) {
                curr = peek.right;
            } else {
                int left = Math.max(0, map.getOrDefault(peek.left, 0));
                int right = Math.max(0, map.getOrDefault(peek.right, 0));

                max = Math.max(max, left + right + peek.val);

                map.put(peek, peek.val + Math.max(left, right));

                last = stack.pop();
            }
        }
    }

    return max;
}
```

