### 3. HashMap with Collision Handling (Linked List 🔥)
```java id="hm3"
class MyHashMap<K, V> {

    class Node {
        K key;
        V value;
        Node next;

        Node(K k, V v) {
            key = k;
            value = v;
        }
    }

    private int capacity = 16;
    private Node[] table;

    MyHashMap() {
        table = new Node[capacity];
    }

    private int hash(K key) {
        return Math.abs(key.hashCode()) % capacity;
    }

    public void put(K key, V value) {
        int i = hash(key);

        if (table[i] == null) {
            table[i] = new Node(key, value);
            return;
        }

        Node curr = table[i];
        while (true) {
            if (curr.key.equals(key)) {
                curr.value = value;
                return;
            }
            if (curr.next == null) break;
            curr = curr.next;
        }

        curr.next = new Node(key, value);
    }

    public V get(K key) {
        Node curr = table[hash(key)];

        while (curr != null) {
            if (curr.key.equals(key)) return curr.value;
            curr = curr.next;
        }
        return null;
    }
}
```

