static int numIslands(char[][] grid) {
    int m = grid.length, n = grid[0].length;
    int count = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == '1') {
                dfs(grid, i, j);
                count++;
            }
        }
    }

    return count;
}

static void dfs(char[][] g, int r, int c) {
    if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] == '0')
        return;

    g[r][c] = '0';

    dfs(g, r+1, c);
    dfs(g, r-1, c);
    dfs(g, r, c+1);
    dfs(g, r, c-1);
}
