Here are **industry-level implementations** of the **Circuit Breaker Pattern (Java)** 👇

---

### 1. Basic Circuit Breaker 🔥 (Closed → Open → Half-Open)
```java id="cb1"
import java.util.concurrent.Callable;

class CircuitBreaker {

    enum State { CLOSED, OPEN, HALF_OPEN }

    private State state = State.CLOSED;

    private int failureCount = 0;
    private final int failureThreshold;
    private final long timeoutMs;

    private long lastFailureTime = 0;

    CircuitBreaker(int threshold, long timeoutMs) {
        this.failureThreshold = threshold;
        this.timeoutMs = timeoutMs;
    }

    public synchronized <T> T call(Callable<T> task) throws Exception {
        long now = System.currentTimeMillis();

        if (state == State.OPEN) {
            if (now - lastFailureTime > timeoutMs) {
                state = State.HALF_OPEN;
            } else {
                throw new RuntimeException("Circuit OPEN");
            }
        }

        try {
            T result = task.call();
            onSuccess();
            return result;
        } catch (Exception e) {
            onFailure();
            throw e;
        }
    }

    private void onSuccess() {
        failureCount = 0;
        state = State.CLOSED;
    }

    private void onFailure() {
        failureCount++;
        lastFailureTime = System.currentTimeMillis();

        if (failureCount >= failureThreshold) {
            state = State.OPEN;
        }
    }
}
```

---

### 2. Circuit Breaker with Half-Open Control 🔥🔥
```java id="cb2"
class CircuitBreaker {

    enum State { CLOSED, OPEN, HALF_OPEN }

    private State state = State.CLOSED;
    private int failures = 0;
    private final int threshold;
    private final long timeout;

    private boolean halfOpenAllowed = true;
    private long lastFailureTime = 0;

    CircuitBreaker(int threshold, long timeout) {
        this.threshold = threshold;
        this.timeout = timeout;
    }

    public synchronized <T> T call(Callable<T> task) throws Exception {
        long now = System.currentTimeMillis();

        if (state == State.OPEN) {
            if (now - lastFailureTime > timeout) {
                state = State.HALF_OPEN;
            } else {
                throw new RuntimeException("Circuit OPEN");
            }
        }

        if (state == State.HALF_OPEN && !halfOpenAllowed) {
            throw new RuntimeException("Half-open busy");
        }

        try {
            if (state == State.HALF_OPEN) halfOpenAllowed = false;

            T result = task.call();
            reset();
            return result;

        } catch (Exception e) {
            recordFailure();
            throw e;
        }
    }

    private void reset() {
        failures = 0;
        state = State.CLOSED;
        halfOpenAllowed = true;
    }

    private void recordFailure() {
        failures++;
        lastFailureTime = System.currentTimeMillis();
        halfOpenAllowed = true;

        if (failures >= threshold) {
            state = State.OPEN;
        }
    }
}
```

