### 2. Print Actual Shortest Path 🔥🔥
```java id="bfs_sp2"
import java.util.*;

static List<Integer> shortestPath(int V, List<List<Integer>> adj, int src, int dest) {
    int[] parent = new int[V];
    Arrays.fill(parent, -1);

    Queue<Integer> q = new LinkedList<>();
    q.offer(src);
    parent[src] = src;

    while (!q.isEmpty()) {
        int node = q.poll();

        if (node == dest) break;

        for (int nei : adj.get(node)) {
            if (parent[nei] == -1) {
                parent[nei] = node;
                q.offer(nei);
            }
        }
    }

    List<Integer> path = new ArrayList<>();
    if (parent[dest] == -1) return path;

    int curr = dest;
    while (curr != src) {
        path.add(curr);
        curr = parent[curr];
    }
    path.add(src);

    Collections.reverse(path);
    return path;
}
```

