static Map<Integer, Integer> shortestPath(Map<Integer, List<Integer>> graph, int src) {
    Map<Integer, Integer> dist = new HashMap<>();
    Queue<Integer> q = new LinkedList<>();

    q.offer(src);
    dist.put(src, 0);

