### 4. Convert to Cycle + Detect 🔥🔥
```java id="ip4"
static Node getIntersection(Node a, Node b) {
    if (a == null || b == null) return null;

    Node temp = a;
    while (temp.next != null) temp = temp.next;

    temp.next = b; // make cycle

    Node slow = a, fast = a;

    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;

        if (slow == fast) break;
    }

    if (fast == null || fast.next == null) return null;

    slow = a;
    while (slow != fast) {
        slow = slow.next;
        fast = fast.next;
    }

    temp.next = null; // restore
    return slow;
}
