### 3. HashSet using Linked List (Manual Node 🔥)
```java id="hs3"
class MyHashSet<K> {

    class Node {
        K key;
        Node next;

        Node(K key) { this.key = key; }
    }

    private int capacity = 16;
    private Node[] table;

    MyHashSet() {
        table = new Node[capacity];
    }

    private int hash(K key) {
        return Math.abs(key.hashCode()) % capacity;
    }

    public void add(K key) {
        int i = hash(key);

        if (table[i] == null) {
            table[i] = new Node(key);
            return;
        }

        Node curr = table[i];
        while (true) {
            if (curr.key.equals(key)) return;
            if (curr.next == null) break;
            curr = curr.next;
        }

        curr.next = new Node(key);
    }

    public boolean contains(K key) {
        Node curr = table[hash(key)];

        while (curr != null) {
            if (curr.key.equals(key)) return true;
            curr = curr.next;
        }
        return false;
    }

    public void remove(K key) {
        int i = hash(key);
        Node curr = table[i], prev = null;

        while (curr != null) {
            if (curr.key.equals(key)) {
                if (prev == null) table[i] = curr.next;
                else prev.next = curr.next;
                return;
            }
            prev = curr;
            curr = curr.next;
        }
    }
}
```

