    static void sort(int[] arr, int start) {
        if (start >= arr.length - 1) return;

        int minIndex = start;

        for (int i = start + 1; i < arr.length; i++) {
            if (arr[i] < arr[minIndex]) {
                minIndex = i;
            }
        }

