### 6. 3-Way Partition (Handles duplicates 🔥🔥)
```java id="qsks6"
import java.util.*;

public class KthSmallest {
    public static void main(String[] args) {
        int[] arr = {3,2,3,1,2,4,5};
        int k = 3;

        System.out.println(select(arr, 0, arr.length - 1, k - 1));
    }

    static int select(int[] arr, int low, int high, int k) {
        int pivot = arr[low];
        int lt = low, gt = high, i = low;

        while (i <= gt) {
            if (arr[i] < pivot) swap(arr, lt++, i++);
            else if (arr[i] > pivot) swap(arr, i, gt--);
            else i++;
        }

        if (k < lt) return select(arr, low, lt - 1, k);
        else if (k > gt) return select(arr, gt + 1, high, k);
        else return pivot;
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
