        }

        int result = quickSelect(arr, 0, arr.length - 1, arr.length - k);
        System.out.println(result);
    }

    static int quickSelect(int[] arr, int l, int r, int k) {
        int pivot = partition(arr, l, r);

        if (pivot == k) return arr[pivot];
        else if (pivot < k) return quickSelect(arr, pivot + 1, r, k);
        else return quickSelect(arr, l, pivot - 1, k);
    }

    static int partition(int[] arr, int l, int r) {
        int pivot = arr[r], i = l;

        for (int j = l; j < r; j++) {
            if (arr[j] <= pivot) {
                int temp = arr[i];
                arr[i++] = arr[j];
                arr[j] = temp;
            }
        }

        int temp = arr[i];
        arr[i] = arr[r];
        arr[r] = temp;

        return i;
    }
}
```

