### 4. Using Binary Indexed Tree (Fenwick Tree 🔥 Advanced)
```java id="ci4d8q"
import java.util.*;

public class CountInversions {

    public static void main(String[] args) {
        int[] arr = {2,4,1,3,5};
        System.out.println(count(arr));
    }

    static int count(int[] arr) {
        int max = Arrays.stream(arr).max().getAsInt();
        int[] BIT = new int[max + 1];

        int invCount = 0;

        for (int i = arr.length - 1; i >= 0; i--) {
            invCount += query(BIT, arr[i] - 1);
            update(BIT, arr[i], 1);
        }

        return invCount;
    }

    static void update(int[] BIT, int i, int val) {
        while (i < BIT.length) {
            BIT[i] += val;
            i += i & -i;
        }
    }

    static int query(int[] BIT, int i) {
        int sum = 0;
        while (i > 0) {
            sum += BIT[i];
            i -= i & -i;
        }
        return sum;
    }
}
```

