### 2. Using Length Count
```java id="rm2"
static Node removeNthFromEnd(Node head, int n) {
    int size = 0;
    Node curr = head;

    while (curr != null) {
        size++;
        curr = curr.next;
    }

    if (n == size) return head.next;

    curr = head;
    for (int i = 1; i < size - n; i++) {
        curr = curr.next;
    }

    curr.next = curr.next.next;
    return head;
}
