Here are **industry-level implementations** of **Autocomplete using Trie** 👇

---

### 1. Basic Autocomplete (Prefix → All Words 🔥)
```java id="ac1"
import java.util.*;

class Trie {

    static class Node {
        Map<Character, Node> children = new HashMap<>();
        boolean isEnd;
    }

    Node root = new Node();

    public void insert(String word) {
        Node curr = root;
        for (char c : word.toCharArray()) {
            curr.children.putIfAbsent(c, new Node());
            curr = curr.children.get(c);
        }
        curr.isEnd = true;
    }

    public List<String> autocomplete(String prefix) {
        List<String> res = new ArrayList<>();
        Node node = find(prefix);

        if (node != null) dfs(node, prefix, res);
        return res;
    }

    private void dfs(Node node, String path, List<String> res) {
        if (node.isEnd) res.add(path);

        for (char c : node.children.keySet()) {
            dfs(node.children.get(c), path + c, res);
        }
    }

    private Node find(String s) {
        Node curr = root;

        for (char c : s.toCharArray()) {
            if (!curr.children.containsKey(c)) return null;
            curr = curr.children.get(c);
        }
        return curr;
    }
}
```

---

### 2. Top-K Autocomplete (Priority Queue 🔥🔥)
```java id="ac2"
import java.util.*;

class Trie {

    static class Node {
        Map<Character, Node> children = new HashMap<>();
        boolean isEnd;
        int freq;
    }

    Node root = new Node();

    public void insert(String word) {
        Node curr = root;

        for (char c : word.toCharArray()) {
            curr.children.putIfAbsent(c, new Node());
            curr = curr.children.get(c);
        }

        curr.isEnd = true;
        curr.freq++;
    }

    public List<String> autocomplete(String prefix, int k) {
        Node node = find(prefix);
        List<Pair> list = new ArrayList<>();

        dfs(node, prefix, list);

        PriorityQueue<Pair> pq = new PriorityQueue<>(
            (a, b) -> b.freq - a.freq
        );

        pq.addAll(list);

        List<String> res = new ArrayList<>();
        while (k-- > 0 && !pq.isEmpty()) {
            res.add(pq.poll().word);
        }

        return res;
    }

    static class Pair {
        String word;
        int freq;

        Pair(String w, int f) {
            word = w;
            freq = f;
        }
    }

    private void dfs(Node node, String path, List<Pair> list) {
        if (node == null) return;

        if (node.isEnd) {
            list.add(new Pair(path, node.freq));
        }

        for (char c : node.children.keySet()) {
            dfs(node.children.get(c), path + c, list);
        }
    }

    private Node find(String s) {
        Node curr = root;

        for (char c : s.toCharArray()) {
            if (!curr.children.containsKey(c)) return null;
            curr = curr.children.get(c);
        }

        return curr;
    }
}
```

