### 3. Iterative Inorder 🔥🔥
```java id="vbst3"
import java.util.*;

static boolean isValidBST(Node root) {
    Stack<Node> stack = new Stack<>();
    Node curr = root;
    Integer prev = null;

    while (curr != null || !stack.isEmpty()) {
        while (curr != null) {
            stack.push(curr);
            curr = curr.left;
        }

        curr = stack.pop();

        if (prev != null && curr.val <= prev) return false;
        prev = curr.val;

        curr = curr.right;
    }

    return true;
}
