```java id="vbst5"
class Node<T extends Comparable<T>> {
    T val;
    Node<T> left, right;
}

static <T extends Comparable<T>> boolean isValidBST(Node<T> root, T min, T max) {
    if (root == null) return true;

    if ((min != null && root.val.compareTo(min) <= 0) ||
        (max != null && root.val.compareTo(max) >= 0))
        return false;

    return isValidBST(root.left, min, root.val) &&
           isValidBST(root.right, root.val, max);
}
