import java.util.*;

public class MajorityElement {
    public static void main(String[] args) {
        int[] nums = {1,1,1,3,3,2,2,2};

        int c1 = 0, c2 = 0, n1 = 0, n2 = 0;

        for (int num : nums) {
            if (num == n1) c1++;
            else if (num == n2) c2++;
            else if (c1 == 0) { n1 = num; c1 = 1; }
            else if (c2 == 0) { n2 = num; c2 = 1; }
            else { c1--; c2--; }
        }

        c1 = 0; c2 = 0;

        for (int num : nums) {
            if (num == n1) c1++;
            else if (num == n2) c2++;
        }

        if (c1 > nums.length / 3) System.out.println(n1);
        if (c2 > nums.length / 3) System.out.println(n2);
    }
}
