        if ((rear + 1) % capacity == front) return false;

        arr[rear] = x;
        rear = (rear + 1) % capacity;
        return true;
    }

    int dequeue() {
        if (front == rear) return -1;

        int val = arr[front];
        front = (front + 1) % capacity;
        return val;
    }

    boolean isEmpty() {
        return front == rear;
    }

    boolean isFull() {
        return (rear + 1) % capacity == front;
    }
}
