### 3. Dynamic Circular Queue (Auto Resize 🔥🔥)
```java id="cq3"
import java.util.*;

public class CircularQueue {
    int[] arr;
    int front, rear, size;

    CircularQueue() {
        arr = new int[2];
        front = 0;
        rear = 0;
        size = 0;
    }

    void enqueue(int x) {
        if (size == arr.length) resize();

        arr[rear] = x;
        rear = (rear + 1) % arr.length;
        size++;
    }

    int dequeue() {
        if (size == 0) throw new RuntimeException("Empty");

        int val = arr[front];
        front = (front + 1) % arr.length;
        size--;
        return val;
    }

    void resize() {
        int[] newArr = new int[arr.length * 2];

        for (int i = 0; i < size; i++) {
            newArr[i] = arr[(front + i) % arr.length];
        }

        arr = newArr;
        front = 0;
        rear = size;
    }
}
```

