Here are **industry-level implementations** of a **Queue using two stacks** 👇

---

### 1. Amortized O(1) (Most Important 🔥)
```java id="qsq1"
import java.util.*;

public class QueueUsingStacks {
    Stack<Integer> in = new Stack<>();
    Stack<Integer> out = new Stack<>();

    void enqueue(int x) {
        in.push(x);
    }

    int dequeue() {
        if (out.isEmpty()) {
            while (!in.isEmpty()) {
                out.push(in.pop());
            }
        }
        if (out.isEmpty()) throw new RuntimeException("Empty");
        return out.pop();
    }

    int peek() {
        if (out.isEmpty()) {
            while (!in.isEmpty()) {
                out.push(in.pop());
            }
        }
        if (out.isEmpty()) throw new RuntimeException("Empty");
        return out.peek();
    }

    public static void main(String[] args) {
        QueueUsingStacks q = new QueueUsingStacks();

        q.enqueue(10);
        q.enqueue(20);
        q.enqueue(30);

        System.out.println(q.dequeue()); // 10
        System.out.println(q.peek());    // 20
    }
}
```

