### 6. Concurrent Version (Atomic + Lock-Free 🔥)
```java id="rl6"
import java.util.concurrent.atomic.AtomicLong;

class SimpleRateLimiter {
    private final long intervalNs;
    private AtomicLong nextAllowedTime = new AtomicLong(0);

    SimpleRateLimiter(int permitsPerSecond) {
        this.intervalNs = 1_000_000_000L / permitsPerSecond;
    }

    public boolean allow() {
        long now = System.nanoTime();
        long allowedTime = nextAllowedTime.get();

        if (now >= allowedTime) {
            return nextAllowedTime.compareAndSet(allowedTime, now + intervalNs);
        }

        return false;
    }
}
