### 2. Detect Cycle Start Node 🔥🔥
```java id="cy2"
public class DetectCycle {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static Node detectCycleStart(Node head) {
        Node slow = head, fast = head;

        // detect cycle
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;

            if (slow == fast) {
                slow = head;

                while (slow != fast) {
                    slow = slow.next;
                    fast = fast.next;
                }
                return slow;
            }
        }
        return null;
    }
}
