### 5. Remove Cycle 🔥🔥
```java id="cy5"
public class DetectCycle {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static void removeCycle(Node head) {
        Node slow = head, fast = head;

        // detect
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;

            if (slow == fast) break;
        }

        if (fast == null || fast.next == null) return;

        slow = head;

        while (slow.next != fast.next) {
            slow = slow.next;
            fast = fast.next;
        }

        fast.next = null; // break cycle
    }
}
