### 5. Generic Partition (Extendable 🔥)
```java id="dnf5n3w"
import java.util.*;

public class Sort012 {
    public static void main(String[] args) {
        int[] arr = {2,0,1,2,1,0};

        partition(arr, 1); // pivot = 1

        System.out.println(Arrays.toString(arr));
    }

    static void partition(int[] arr, int pivot) {
        int low = 0, high = arr.length - 1, i = 0;

        while (i <= high) {
            if (arr[i] < pivot) {
                swap(arr, i++, low++);
            } else if (arr[i] > pivot) {
                swap(arr, i, high--);
            } else {
                i++;
            }
        }
    }

    static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}
