### 4. In-place Merge (No extra nodes 🔥)
```java id="ml4"
static Node merge(Node l1, Node l2) {
    if (l1 == null) return l2;
    if (l2 == null) return l1;

    if (l1.val > l2.val) {
        Node temp = l1;
        l1 = l2;
        l2 = temp;
    }

    Node res = l1;

    while (l1 != null && l2 != null) {
        Node prev = null;

        while (l1 != null && l1.val <= l2.val) {
            prev = l1;
            l1 = l1.next;
        }

        prev.next = l2;

        Node temp = l1;
        l1 = l2;
        l2 = temp;
    }

    return res;
}
