### 1. Optimal LFU (HashMap + Frequency List 🔥🔥 O(1))
```java id="lfu1"
import java.util.*;

class Node {
    int key, value, freq;
    Node prev, next;

    Node(int k, int v) {
        key = k;
        value = v;
        freq = 1;
    }
}

class DoublyLinkedList {
    Node head = new Node(0,0);
    Node tail = new Node(0,0);

    DoublyLinkedList() {
        head.next = tail;
        tail.prev = head;
    }

    void add(Node node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    Node removeLast() {
        if (tail.prev == head) return null;
        Node node = tail.prev;
        remove(node);
        return node;
    }

    boolean isEmpty() {
        return head.next == tail;
    }
}

public class LFUCache {
    int capacity, minFreq;
    Map<Integer, Node> map;
    Map<Integer, DoublyLinkedList> freqMap;

    public LFUCache(int capacity) {
        this.capacity = capacity;
        map = new HashMap<>();
        freqMap = new HashMap<>();
    }

    public int get(int key) {
        if (!map.containsKey(key)) return -1;

        Node node = map.get(key);
        update(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (capacity == 0) return;

        if (map.containsKey(key)) {
            Node node = map.get(key);
            node.value = value;
            update(node);
            return;
        }

        if (map.size() == capacity) {
            DoublyLinkedList minList = freqMap.get(minFreq);
            Node evict = minList.removeLast();
            map.remove(evict.key);
        }

        Node node = new Node(key, value);
        minFreq = 1;

        freqMap.computeIfAbsent(1, k -> new DoublyLinkedList()).add(node);
        map.put(key, node);
    }

    private void update(Node node) {
        int freq = node.freq;
        DoublyLinkedList list = freqMap.get(freq);

        list.remove(node);
        if (freq == minFreq && list.isEmpty()) {
            minFreq++;
        }

        node.freq++;
        freqMap.computeIfAbsent(node.freq, k -> new DoublyLinkedList()).add(node);
    }
}
```

