import java.util.*;

public class LFUCache {
    private final int capacity;
    private final Map<Integer, Integer> valueMap = new HashMap<>();
    private final Map<Integer, Integer> freqMap = new HashMap<>();

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public synchronized int get(int key) {
        if (!valueMap.containsKey(key)) return -1;

        freqMap.put(key, freqMap.get(key) + 1);
        return valueMap.get(key);
    }

    public synchronized void put(int key, int value) {
        if (capacity == 0) return;

        if (valueMap.size() >= capacity) {
            int minFreq = Collections.min(freqMap.values());
            for (int k : freqMap.keySet()) {
                if (freqMap.get(k) == minFreq) {
                    valueMap.remove(k);
                    freqMap.remove(k);
                    break;
                }
            }
        }

        valueMap.put(key, value);
        freqMap.put(key, 1);
    }
}
