### 3. Stack Based (Simple ⚠️)
```java id="kg3"
import java.util.*;

static Node reverseKGroup(Node head, int k) {
    Stack<Node> stack = new Stack<>();
    Node curr = head;

    Node dummy = new Node(0);
    Node tail = dummy;

    while (curr != null) {
        int count = 0;
        Node temp = curr;

        while (temp != null && count < k) {
            stack.push(temp);
            temp = temp.next;
            count++;
        }

        if (count < k) {
            tail.next = curr;
            break;
        }

        while (!stack.isEmpty()) {
            tail.next = stack.pop();
            tail = tail.next;
        }

        curr = temp;
    }

    tail.next = null;
    return dummy.next;
}
