### 4. Reverse Alternate K Groups 🔥
```java id="kg4"
static Node reverseAltK(Node head, int k) {
    Node curr = head, prev = null, next = null;
    int count = 0;

    while (curr != null && count < k) {
        next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
        count++;
    }

    if (head != null) {
        head.next = curr;
    }

    count = 0;
    while (curr != null && count < k - 1) {
        curr = curr.next;
        count++;
    }

    if (curr != null) {
        curr.next = reverseAltK(curr.next, k);
    }

    return prev;
}
```

