static Node reverseKGroup(Node head, int k) {
    if (head == null || k <= 1) return head;

    Node curr = head;
    int count = 0;

    while (curr != null && count < k) {
        curr = curr.next;
        count++;
    }

    if (count < k) return head;

    Node prev = null, next = null;
    curr = head;
    count = 0;

    while (curr != null && count < k) {
        next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
        count++;
    }

    head.next = reverseKGroup(curr, k);

    return prev;
}
