import java.util.concurrent.atomic.AtomicLong;

class Snowflake {

    private AtomicLong lastTs = new AtomicLong(-1);
    private AtomicLong seq = new AtomicLong(0);

    public long nextId() {
        long ts = System.currentTimeMillis();

        if (ts == lastTs.get()) {
            seq.set((seq.get() + 1) & 4095);
        } else {
            seq.set(0);
            lastTs.set(ts);
        }

        return (ts << 22) | seq.get();
    }
}
