        int i=0,j=0,k=0;

        while(i<a.length && j<b.length){
            merged[k++] = (a[i] < b[j]) ? a[i++] : b[j++];
        }

        while(i<a.length) merged[k++] = a[i++];
        while(j<b.length) merged[k++] = b[j++];

        int n = merged.length;

        if(n % 2 == 0)
            System.out.println((merged[n/2 - 1] + merged[n/2]) / 2.0);
        else
            System.out.println(merged[n/2]);
    }
}
