## 6. Express API (PDF CRUD endpoints 🔥)

```js
// server.js
const express = require('express');
const fs = require('fs');
const { PDFDocument, StandardFonts } = require('pdf-lib');
const pdfParse = require('pdf-parse');

const app = express();
app.use(express.json());

// CREATE
app.post('/pdf', async (req, res) => {
  const { text } = req.body;

  const pdfDoc = await PDFDocument.create();
  const page = pdfDoc.addPage();
  const font = await pdfDoc.embedFont(StandardFonts.Helvetica);

  page.drawText(text || 'Default Text', { x: 50, y: 500 });

  const bytes = await pdfDoc.save();
  fs.writeFileSync('file.pdf', bytes);

  res.send('PDF created');
});

// READ
app.get('/pdf', async (req, res) => {
  const data = await pdfParse(fs.readFileSync('file.pdf'));
  res.send(data.text);
});

// UPDATE
app.put('/pdf', async (req, res) => {
  const pdfDoc = await PDFDocument.load(fs.readFileSync('file.pdf'));
  const page = pdfDoc.getPages()[0];

  page.drawText('Updated via API', { x: 50, y: 450 });

  const bytes = await pdfDoc.save();
  fs.writeFileSync('file.pdf', bytes);

  res.send('PDF updated');
});

// DELETE
app.delete('/pdf', (req, res) => {
  fs.unlinkSync('file.pdf');
  res.send('PDF deleted');
});

app.listen(3000, () => console.log('Server running on 3000'));
```

