```javascript
const mongoose = require("mongoose");

const nestedCommentSchema = new mongoose.Schema({
  text: String,
  createdAt: { type: Date, default: Date.now },
});

const commentSchema = new mongoose.Schema({
  text: String,
  createdAt: { type: Date, default: Date.now },
  nestedComments: [nestedCommentSchema],
});

const tweetSchema = new mongoose.Schema({
  content: String,
  createdAt: { type: Date, default: Date.now },
  comments: [commentSchema],
});

const Tweet = mongoose.model("Tweet", tweetSchema);

module.exports = Tweet;
```

In this schema structure, the `Tweet` schema contains an array of `comments`, and each `comment` contains an array of `nestedComments`. Each schema (`Tweet`, `Comment`, and `NestedComment`) has its own properties and nested structures, making it more organized and easier to manage.

