```jsx
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function Comment({ text, nestedComments }) {
  return (
    <div className="comment">
      <p>{text}</p>
      {nestedComments && nestedComments.map((comment, index) => (
        <Comment key={index} text={comment.text} nestedComments={comment.nestedComments} />
      ))}
    </div>
  );
}

function Tweet({ content, comments }) {
  return (
    <div className="tweet">
      <p>{content}</p>
      {comments && comments.map((comment, index) => (
        <Comment key={index} text={comment.text} nestedComments={comment.nestedComments} />
      ))}
    </div>
  );
}

function TweetApp() {
  const [tweets, setTweets] = useState([]);

  useEffect(() => {
    async function fetchTweets() {
      try {
        const response = await axios.get('/tweets'); // Assuming your server is running on the same host/port
        setTweets(response.data);
      } catch (error) {
        console.error('Error fetching tweets:', error);
      }
    }

    fetchTweets();
  }, []);

  return (
    <div className="tweet-app">
      {tweets.map((tweet, index) => (
        <Tweet key={index} content={tweet.content} comments={tweet.comments} />
      ))}
    </div>
  );
}

export default TweetApp;
```

Make sure you have Axios installed (`npm install axios`) to handle HTTP requests in your React app. In this example, the `useEffect` hook fetches the tweets when the component mounts. Adjust the endpoint URL as needed based on where your Express server is running.

