     "deleteUser": "उपयोगकर्ता हटाएं",
     "name": "नाम",
     "actions": "क्रियाएं",
     "save": "सहेजें",
     "cancel": "रद्द करें"
   }
   ```

2. **Update the locale map**:

   Add Hindi to the `localeMap` in the `src/i18n.js` file.

   `src/i18n.js`:
   ```javascript
   import React from 'react';
   import { IntlProvider } from 'react-intl';
   import English from '../public/locales/en.json';
   import French from '../public/locales/fr.json';
   import Hindi from '../public/locales/hi.json';

   const localeMap = {
     en: English,
     fr: French,
     hi: Hindi,
   };

   const I18nProvider = ({ locale, children }) => (
     <IntlProvider locale={locale} messages={localeMap[locale]}>
       {children}
     </IntlProvider>
   );

   export default I18nProvider;
   ```

3. **Update the App component**:

   Add an option to change the language to Hindi.

   `src/App.js`:
   ```javascript
   import React, { useState } from 'react';
   import I18nProvider from './i18n';
   import UserList from './components/UserList';
   import AddUser from './components/AddUser';
   import EditUser from './components/EditUser';
   import DeleteUser from './components/DeleteUser';

   const App = () => {
     const [locale, setLocale] = useState('en');
     const [users, setUsers] = useState([]);
     const [editingUser, setEditingUser] = useState(null);
     const [deletingUser, setDeletingUser] = useState(null);

     const changeLanguage = (lng) => {
       setLocale(lng);
     };

     const handleAddUser = (user) => {
       setUsers([...users, user]);
     };

     const handleEditUser = (user) => {
       setEditingUser(user);
     };

     const handleUpdateUser = (user) => {
       setUsers(users.map((u) => (u.id === user.id ? user : u)));
       setEditingUser(null);
     };

     const handleDeleteUser = (id) => {
       setUsers(users.filter((user) => user.id !== id));
       setDeletingUser(null);
     };

     return (
       <I18nProvider locale={locale}>
         <div className="App">
           <button onClick={() => changeLanguage('en')}>English</button>
           <button onClick={() => changeLanguage('fr')}>Français</button>
           <button onClick={() => changeLanguage('hi')}>हिन्दी</button>

           <AddUser onAdd={handleAddUser} />
           <UserList users={users} onEdit={handleEditUser} onDelete={(id) => setDeletingUser(id)} />

           {editingUser && (
             <EditUser
               currentUser={editingUser}
               onUpdate={handleUpdateUser}
               onCancel={() => setEditingUser(null)}
             />
           )}

           {deletingUser && (
             <DeleteUser
               user={users.find((user) => user.id === deletingUser)}
               onDelete={handleDeleteUser}
               onCancel={() => setDeletingUser(null)}
             />
           )}
         </div>
       </I18nProvider>
     );
   };

   export default App;
