const express = require('express');
const { graphqlHTTP } = require('express-graphql');
const { GraphQLSchema, GraphQLObjectType, GraphQLString, GraphQLList, GraphQLNonNull } = require('graphql');
const { MongoClient, ObjectId } = require('mongodb');

const app = express();

// MongoDB setup
const url = 'mongodb://localhost:27017'; // Replace with your MongoDB connection URL
const dbName = 'your-database-name'; // Replace with your database name
const client = new MongoClient(url, { useNewUrlParser: true });

// Connect to MongoDB
client.connect().then(() => {
  const db = client.db(dbName);
  const collection = db.collection('activities');

  // Define GraphQL types
  const activityType = new GraphQLObjectType({
    name: 'Activity',
    fields: () => ({
      _id: { type: GraphQLString },
      title: { type: GraphQLString },
      description: { type: GraphQLString },
      date: { type: GraphQLString },
      createdDate: { type: GraphQLString },
      shouldContinue: { type: GraphQLString },
    }),
  });

  // Define the Root Query
  const rootQuery = new GraphQLObjectType({
    name: 'Query',
    fields: {
      activities: {
        type: new GraphQLList(activityType),
        resolve: async () => {
          const activities = await collection.find({}).toArray();
          return activities;
        },
      },
    },
  });

  // Define the Root Mutation
  const rootMutation = new GraphQLObjectType({
    name: 'Mutation',
    fields: {
      createActivity: {
        type: activityType,
        args: {
          title: { type: GraphQLNonNull(GraphQLString) },
          description: { type: GraphQLNonNull(GraphQLString) },
          date: { type: GraphQLNonNull(GraphQLString) },
          shouldContinue: { type: GraphQLNonNull(GraphQLString) },
        },
        resolve: async (_, args) => {
          const result = await collection.insertOne(args);
          return result.ops[0];
        },
      },
      updateActivity: {
        type: activityType,
        args: {
          id: { type: GraphQLNonNull(GraphQLString) },
          title: { type: GraphQLString },
          description: { type: GraphQLString },
          date: { type: GraphQLString },
          shouldContinue: { type: GraphQLString },
        },
        resolve: async (_, args) => {
          const result = await collection.findOneAndUpdate(
            { _id: ObjectId(args.id) },
            { $set: { ...args } },
            { returnOriginal: false }
          );
          return result.value;
        },
      },
      deleteActivity: {
        type: GraphQLString,
        args: {
          id: { type: GraphQLNonNull(GraphQLString) },
        },
        resolve: async (_, args) => {
          await collection.deleteOne({ _id: ObjectId(args.id) });
          return 'Activity deleted successfully';
        },
      },
    },
  });

  const schema = new GraphQLSchema({
    query: rootQuery,
    mutation: rootMutation,
  });

  // Use express-graphql as middleware
  app.use(
    '/graphql',
    graphqlHTTP({
      schema,
      graphiql: true, // Enable GraphiQL for testing in the browser
    })
  );

  app.listen(4000, () => {
    console.log('Server is running on port 4000');
  });
});
